const baseUrl = $env.KOMMO_BASE_URL;
const token = $env.KOMMO_API_TOKEN;
const fieldMap = {
  agenda: Number($env.KOMMO_FIELD_AGENDA_ID),
  cita_asistida: Number($env.KOMMO_FIELD_CITA_ASISTIDA_ID),
  cotizacion: Number($env.KOMMO_FIELD_COTIZACION_ID),
  campaign: Number($env.KOMMO_FIELD_CAMPAIGN_ID),
  adset: Number($env.KOMMO_FIELD_ADSET_ID),
  ad: Number($env.KOMMO_FIELD_AD_ID),
};

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const toIso = (unixSeconds) => (unixSeconds ? new Date(unixSeconds * 1000).toISOString() : null);

async function kommoGet(pathname, qs) {
  await sleep(350); // ~3 req/s, Kommo caps at 7 req/s
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}${pathname}`,
    qs,
    headers: { Authorization: `Bearer ${token}` },
    json: true,
  });
}

const usersRes = await kommoGet.call(this, '/api/v4/users', { limit: 250 });
const userNameById = new Map((usersRes?._embedded?.users ?? []).map((u) => [u.id, u.name]));

const pipelinesRes = await kommoGet.call(this, '/api/v4/leads/pipelines', { with: 'statuses' });
const statusType = new Map();
const statusRows = [];
for (const p of pipelinesRes?._embedded?.pipelines ?? []) {
  for (const s of p._embedded?.statuses ?? []) {
    let type = 'open';
    if (s.type === 1 || s.id === 142) type = 'won';
    if (s.type === 2 || s.id === 143) type = 'lost';
    statusType.set(s.id, type);
    statusRows.push({
      json: {
        __type: 'status',
        pipeline_id: p.id,
        status_id: s.id,
        pipeline_name: p.name,
        status_name: s.name,
        sort: s.sort ?? null,
        status_type: type,
      },
    });
  }
}

const lossRes = await kommoGet.call(this, '/api/v4/leads/loss_reasons', { limit: 250 });
const lossReasonById = new Map((lossRes?._embedded?.loss_reasons ?? []).map((r) => [r.id, r.name]));
const lossRows = (lossRes?._embedded?.loss_reasons ?? []).map((r) => ({
  json: { __type: 'loss_reason', loss_reason_id: r.id, name: r.name },
}));

function extractCustomField(lead, fieldId) {
  if (!fieldId) return null;
  const cf = (lead.custom_fields_values || []).find((f) => f.field_id === fieldId);
  return cf?.values?.[0]?.value ?? null;
}
function extractCustomFieldDate(lead, fieldId) {
  const raw = extractCustomField(lead, fieldId);
  const n = Number(raw);
  return raw != null && Number.isFinite(n) ? toIso(n) : null;
}

const leadRows = [];
let page = 1;
for (;;) {
  const res = await kommoGet.call(this, '/api/v4/leads', { page, limit: 250, with: 'custom_fields_values' });
  const leads = res?._embedded?.leads ?? [];
  for (const lead of leads) {
    const type = statusType.get(lead.status_id) ?? 'open';
    leadRows.push({
      json: {
        __type: 'lead',
        lead_id: lead.id,
        name: lead.name,
        price: lead.price ?? 0,
        pipeline_id: lead.pipeline_id,
        status_id: lead.status_id,
        responsible_user_id: lead.responsible_user_id,
        responsible_user_name: userNameById.get(lead.responsible_user_id) ?? null,
        created_at: toIso(lead.created_at),
        updated_at: toIso(lead.updated_at),
        closed_at: toIso(lead.closed_at),
        is_won: type === 'won',
        is_lost: type === 'lost',
        loss_reason_id: lead.loss_reason_id ?? null,
        loss_reason_name: lead.loss_reason_id ? (lossReasonById.get(lead.loss_reason_id) ?? null) : null,
        campaign: extractCustomField(lead, fieldMap.campaign),
        adset: extractCustomField(lead, fieldMap.adset),
        ad: extractCustomField(lead, fieldMap.ad),
        fecha_agenda: extractCustomFieldDate(lead, fieldMap.agenda),
        fecha_cita_asistida: extractCustomFieldDate(lead, fieldMap.cita_asistida),
        fecha_cotizacion: extractCustomFieldDate(lead, fieldMap.cotizacion),
      },
    });
  }
  if (!res?._links?.next || leads.length === 0) break;
  page += 1;
}

return [...statusRows, ...lossRows, ...leadRows];
